#!/usr/bin/env bash
# Builds the two installer scripts from pve/install-parts:
#
#   pve/install.sh      host half, runs on the Proxmox host        (top-level parts + shared/)
#   pve/ct-install.sh   in-container half, runs in any container  (ct/ parts + ct/distro/ + shared/)
#
# Both stay ONE self-contained file each (committed, shipped in the release bundle) because they are
# run as `bash -c "$(curl …)"` and can't source anything next to them. Edit the parts, never the
# generated files.
#
# Part order: the header, the settings, shared/*.sh, then the other parts by name; the last one holds main.
# Files in install-parts/files/{bin,systemd,udev}/ (helper scripts, udev rules, systemd units; they may
# hold @VAR@ placeholders, see render_file() in shared/20-engine.sh) are inlined as heredocs into
# get_file(). Each script embeds only the files listed below.
#
#   pve/build.sh            regenerate both scripts
#   pve/build.sh --check    fail if one is stale or has syntax errors (CI)
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")"

HOST_PARTS=(install-parts/00-header.sh install-parts/10-config.sh install-parts/shared/*.sh install-parts/[2-9]*.sh)
HOST_FILES=(bin/cdh-input-node.sh udev/72-cdh-input-node.rules)

CT_PARTS=(install-parts/ct/00-header.sh install-parts/ct/10-ct-config.sh install-parts/shared/*.sh install-parts/ct/distro/*.sh install-parts/ct/[2-9]*.sh)
CT_FILES=(udev/60-lxc-virtual-input.rules systemd/cloud-desktop-host.service systemd/cdh-update.service systemd/cdh-update.timer)

# get_file <dir/name>: prints install-parts/files/<dir/name>
render_embedded() {
  local f name tag=CDH_EMBEDDED_EOF
  echo "# ════ install-parts/files/* (inlined by build.sh) ════"
  echo "get_file() {"
  echo '  case $1 in'
  for name in "$@"; do
    f=install-parts/files/$name
    [[ -f $f ]] || { echo "build.sh: $f does not exist" >&2; exit 1; }
    if grep -qx "$tag" "$f"; then echo "build.sh: $f contains the line $tag" >&2; exit 1; fi
    echo "    $name)"
    echo "      cat <<'$tag'"
    cat "$f"
    echo "$tag"
    echo "      ;;"
  done
  echo '    *) echo "get_file: no file $1" >&2; return 1 ;;'
  echo "  esac"
  echo "}"
}

# render <script name> <part>… -- <embedded file>…
render() {
  local out=$1 f first=1 parts=() files=()
  shift
  while (($#)) && [[ $1 != -- ]]; do parts+=("$1"); shift; done
  shift
  files=("$@")
  for f in "${parts[@]}"; do
    if ((first)); then   # the header: shebang first, then the generated-file banner
      head -n1 "$f"
      echo "# GENERATED by pve/build.sh from pve/install-parts: do not edit, edit the parts and rebuild ($out)."
      tail -n +2 "$f"
      echo
      render_embedded "${files[@]}"
      first=0
    else
      echo
      echo "# ════ ${f} ════"
      cat "$f"
    fi
  done
}

status=0
build() {
  local out=$1 tmp
  shift
  tmp=$(mktemp)
  render "$out" "$@" >"$tmp"
  bash -n "$tmp" || { echo "build.sh: syntax error in the merged $out" >&2; rm -f "$tmp"; exit 1; }
  if [[ ${CHECK:-0} == 1 ]]; then
    if ! cmp -s "$tmp" "$out"; then
      echo "pve/$out is out of date: run pve/build.sh and commit the result" >&2
      status=1
    else
      echo "pve/$out is up to date"
    fi
  else
    cat "$tmp" >"$out"
    chmod 0755 "$out"
    echo "built pve/$out"
  fi
  rm -f "$tmp"
}

[[ ${1:-} != --check ]] || CHECK=1
build install.sh "${HOST_PARTS[@]}" -- "${HOST_FILES[@]}"
build ct-install.sh "${CT_PARTS[@]}" -- "${CT_FILES[@]}"
exit "$status"
